function filterCourses() {
  const target = document.getElementById('catalog-courses') || document.getElementById('home-courses');
  if (!target) return;
  const term = (document.getElementById('course-search')?.value || '').toLowerCase().trim();
  const level = document.getElementById('course-level')?.value || '';
  let filtered = courses.filter(c => (activeCategory === 'All Courses' || c.category === activeCategory) && (!level || c.level === level) && `${c.title} ${c.category} ${c.description}`.toLowerCase().includes(term));
  const sort = document.getElementById('course-sort')?.value;
  if (sort === 'price-low') filtered.sort((a, b) => a.price - b.price);
  else if (sort === 'price-high') filtered.sort((a, b) => b.price - a.price);
  else if (sort === 'rating') filtered.sort((a, b) => Number(b.rating) - Number(a.rating));
  else if (target.id === 'catalog-courses') filtered.sort((a, b) => b.reviews - a.reviews);
  if (target.id === 'home-courses') filtered = filtered.slice(0, 8);
  target.innerHTML = filtered.length ? filtered.map(courseCard).join('') : '<div class="empty-state"><h3>No courses found</h3><p>Try a different keyword or choose another category.</p><button class="btn btn-blue" data-action="reset-filters">Reset filters ↗</button></div>';
  const count = document.getElementById('course-result-count');
  if (count) count.textContent = `Showing ${filtered.length} course${filtered.length === 1 ? '' : 's'}`;
}

