document.addEventListener('keydown', event => { const tab = event.target.closest('[role="tab"]'); if (tab && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) { const siblings = [...tab.closest('[role="tablist"]').querySelectorAll('[role="tab"]')]; const index = siblings.indexOf(tab); const next = event.key === 'Home' ? siblings[0] : event.key === 'End' ? siblings[siblings.length - 1] : siblings[(index + (event.key === 'ArrowRight' ? 1 : -1) + siblings.length) % siblings.length]; event.preventDefault(); next.focus(); next.click(); } });
