const themeToggle = document.querySelector('.theme-toggle');
function applyTheme(theme) {
  document.documentElement.dataset.theme = theme;
  themeToggle.textContent = theme === 'dark' ? '\u2600' : '\u263d';
  themeToggle.setAttribute('aria-pressed', String(theme === 'dark'));
  themeToggle.setAttribute('aria-label', `Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`);
  themeToggle.title = themeToggle.getAttribute('aria-label');
}
let preferredTheme;
try { preferredTheme = localStorage.getItem('ecoach-theme'); } catch { }
applyTheme(preferredTheme === 'light' || preferredTheme === 'dark' ? preferredTheme : (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'));
themeToggle.addEventListener('click', () => {
  const theme = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
  applyTheme(theme);
  try { localStorage.setItem('ecoach-theme', theme); } catch { }
});
